/**
 * A verification-code field drawn as separate digit cells (`design/components/otp-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/otp-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  Each,
  agentMember,
  claimSlot,
  createCell,
  createDerived,
  elementRef,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/controls/otp-input.module.css'

export type OTPLength = NonNullable<OTPInputProps['length']>

export interface OTPInputProps {
  'aria-describedby'?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  'aria-label'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
  defaultValue?: string
  disabled?: boolean
  id?: string
  /**
   * Usually set by FormField, for example for "That code didn't match".
   */
  invalid?: boolean
  /**
   * The code length, 4 or 6, which are the lengths real code systems use.
   */
  length?: 4 | 6
  /**
   * Set directly on the real input, so no hidden input is needed.
   */
  name?: string
  /**
   * Never reports a non-digit.
   */
  onChange?: (value: string) => void
  /**
   * Fires once, after `onChange`, when the code becomes full. Apps that want to verify without a
   * Verify button submit from here.
   */
  onComplete?: (code: string) => void
  /**
   * Digits only. Every write path filters and truncates to `length`.
   */
  value?: string
}

/** A verification-code field drawn as separate digit cells. */
export default function OTPInput(given: OTPInputProps): JSX.Element {
  const props = mergeProps(
    { length: 6, invalid: false, disabled: false } as Defaults<
      OTPInputProps,
      'length' | 'invalid' | 'disabled'
    >,
    claimSlot(given, 'field'),
  )
  const field = elementRef<HTMLElement>()
  const uncontrolled = createCell(
    (props.defaultValue ?? '').replace(/\D/g, '').slice(0, props.length),
  )
  const focused = createCell(false)
  const code = createDerived(() =>
    (props.value ?? uncontrolled.value).replace(/\D/g, '').slice(0, props.length),
  )
  const caretIndex = createDerived(() =>
    code.value.length === props.length ? props.length - 1 : code.value.length,
  )
  const cells = createDerived(() => Array.from({ length: props.length }, (_, index) => index))
  const commit = createDerived(
    () => (next: string) =>
      ((before: string) => (
        (uncontrolled.value = next),
        next !== before && props.onChange?.(next),
        next.length === props.length && before.length < props.length && props.onComplete?.(next)
      ))(code.value),
  )
  const receive = createDerived(
    () => (event: Event) =>
      ((input: HTMLInputElement) => (
        commit.value(input.value.replace(/\D/g, '').slice(0, props.length)),
        (input.value = code.value)
      ))(event.target as HTMLInputElement),
  )
  const receivePaste = createDerived(
    () => (event: ClipboardEvent) => (
      event.preventDefault(),
      commit.value(
        (event.clipboardData?.getData('text') ?? '').replace(/\D/g, '').slice(0, props.length),
      ),
      ((event.target as HTMLInputElement).value = code.value)
    ),
  )
  const pinCaret = createDerived(
    () => (event: Event) =>
      ((node: HTMLInputElement) =>
        (node.selectionStart !== code.value.length || node.selectionEnd !== code.value.length) &&
        node.setSelectionRange(code.value.length, code.value.length))(
        event.currentTarget as HTMLInputElement,
      ),
  )
  let release1: (() => void) | undefined
  const effect1 = () => {
    release1?.()
    const ran = agentMember({
      member: 'OTPInput',
      element: () => field.value,
      state: () => ({ value: code.value, disabled: props.disabled, invalid: props.invalid }),
      actions: {},
      secret: ['value'],
    })
    release1 = () => {
      ran()
    }
  }
  onMount(effect1)
  onCleanup(() => release1?.())
  return (
    <div
      class={styles.root}
      data-invalid={props.invalid ? '' : undefined}
      data-disabled={props.disabled ? '' : undefined}
      data-member="otp-input"
    >
      {/* field */}
      <input
        class={styles.input}
        type="text"
        value={code.value}
        disabled={props.disabled}
        name={props.name}
        id={props.id}
        inputmode="numeric"
        autocomplete="one-time-code"
        spellcheck="false"
        autocapitalize="off"
        autocorrect="off"
        maxlength={props.length}
        aria-label={props['aria-label']}
        aria-labelledby={props['aria-labelledby']}
        aria-describedby={props['aria-describedby']}
        aria-required={props['aria-required']}
        aria-invalid={props.invalid ? true : undefined}
        oninput={($event: InputEvent) => receive.value($event)}
        onpaste={($event: ClipboardEvent) => receivePaste.value($event)}
        onkeydown={($event: KeyboardEvent) =>
          ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End'].includes($event.key) &&
          $event.preventDefault()
        }
        onselect={($event: Event) => pinCaret.value($event)}
        onmouseup={($event: MouseEvent) => pinCaret.value($event)}
        onkeyup={($event: KeyboardEvent) => pinCaret.value($event)}
        onfocus={($event: FocusEvent) => ((focused.value = true), pinCaret.value($event))}
        onblur={() => (focused.value = false)}
        ref={field.attach}
      />
      <Each of={cells.value} by={(index) => index} renew>
        {(index) => (
          <span
            class={styles.cell}
            aria-hidden="true"
            data-filled={code.value[index] !== undefined ? '' : undefined}
            data-caret={focused.value && index === caretIndex.value ? '' : undefined}
          >
            {code.value[index] !== undefined ? (
              <Each of={[code.value[index]]} by={(digit) => `${index}-${digit}`} renew>
                {(digit) => <span class={styles.digit}>{digit}</span>}
              </Each>
            ) : null}
          </span>
        )}
      </Each>
    </div>
  )
}

OTPInput.controlKind = 'field'
